<?php
session_start(); require_once '../conexion.php';
if(!isset($_SESSION['usuario_id'])||$_SESSION['rol']!=='operario'){header('Location: ../login.php');exit;}
$pedido_id=isset($_GET['id'])?(int)$_GET['id']:0;$operario_id=(int)$_SESSION['usuario_id'];$mensaje='';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['confirmar'])){
 $stmt=$conexion->prepare("UPDATE pedidos SET estado='Completado' WHERE id=? AND operario_id=? AND estado IN ('Pendiente','En proceso')");$stmt->bind_param('ii',$pedido_id,$operario_id);$stmt->execute();$ok=$stmt->affected_rows>0;$stmt->close();if($ok){header('Location: dashboard.php');exit;} $mensaje='No se pudo actualizar el pedido.';
}
$stmt=$conexion->prepare("SELECT id,estado,total_productos FROM pedidos WHERE id=? AND operario_id=?");$stmt->bind_param('ii',$pedido_id,$operario_id);$stmt->execute();$resultado=$stmt->get_result();if($resultado->num_rows!==1){$stmt->close();header('Location: dashboard.php');exit;}$pedido=$resultado->fetch_assoc();$stmt->close();
?>
